import unittest,tempfile,pathlib,shutil,json,subprocess,uuid,datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
class HistoryQueueTransport(unittest.TestCase):
 def test_history_pending_and_ready_readback(self):
  with tempfile.TemporaryDirectory() as td:
   root=pathlib.Path(td);(root/'deploy').mkdir();(root/'private/meta-account-lookups').mkdir(parents=True);shutil.copy2(ROOT/'deploy/meta-lookup-queue.py',root/'deploy/meta-lookup-queue.py');rid=str(uuid.uuid4());row={'request_id':rid,'account_id':'202607','platform':'history','period':'2026-07','actor':'rodolfo','status':'pending','requested_at':datetime.datetime.now(datetime.timezone.utc).isoformat()};p=root/'private/meta-account-lookups'/(rid+'.json');p.write_text(json.dumps(row));wait=subprocess.run(['python3',str(root/'deploy/meta-lookup-queue.py'),'wait'],capture_output=True,text=True,timeout=5,check=True);queued=json.loads(wait.stdout);self.assertEqual(queued[0]['period'],'2026-07');self.assertEqual(queued[0]['actor'],'rodolfo');ready={**queued[0],'status':'ready','updated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'captured_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'changed':False,'documents':6,'policy_correction':{'authority':'1547697182948458611','currency':'CAD'}};done=subprocess.run(['python3',str(root/'deploy/meta-lookup-queue.py'),'complete'],input=json.dumps([ready]),capture_output=True,text=True,timeout=5,check=True);self.assertTrue(json.loads(done.stdout)['readback']);saved=json.loads(p.read_text());self.assertEqual(saved['documents'],6);self.assertEqual(saved['policy_correction']['currency'],'CAD')
if __name__=='__main__':unittest.main()
